INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'Geography', 'Unit 6', 'Molarum Grade 10 — Geography Unit 6: Human–Natural Environment Interactions', 'Source-grounded Molarum Grade 10 Geography questions for Unit 6: Human–Natural Environment Interactions.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('00a4cde6-66d5-4354-8e02-ad9ba9296e7c'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'multiple_choice', 'Which SDG in the excerpt emphasizes promoting entrepreneurship, job creation and achieving full and productive employment and decent work for all by 2030?', 'Goal 8', 'The excerpt states under Goal 8 that the SDGs promote sustained economic growth, encouraging entrepreneurship and job creation and aims to achieve full and productive employment and decent work by 2030.', 0),('a8b41e70-e64b-4153-8ee6-17cfeb5bab85'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'multiple_choice', 'Which SDG described in the excerpt identifies technological progress as key to solving economic and environmental challenges?', 'Goal 9', 'The excerpt explains Goal 9 by stating that technological progress is the key to finding lasting solutions to economic and environmental challenges and promoting industry, innovation and infrastructure.', 1),('2494ecb9-e8fe-4f8e-870f-19d2c95af651'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'multiple_choice', 'Which SDG calls for urgently reducing our ecological footprint by changing the way we produce and consume goods and resources?', 'Goal 12', 'The excerpt describes Goal 12 as aiming to reduce the ecological footprint by changing how we produce and consume goods, manage shared resources, and dispose of toxic waste and pollutants.', 2),('ae0c49f8-ce2c-497e-8434-2ffa0e5a90ea'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'multiple_choice', 'What is the maximum possible Religious Diversity Index (RDI) score if each of the eight major religion groups constitutes an equal share of the population?', '10', 'The excerpt states the RDI is on a scale from 0–10, with 10 being the maximum possible diversity if each of the eight groups constitutes an equal share.', 3),('923f7cb2-2995-4c39-8688-e813a3cf2928'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'multiple_choice', 'According to the excerpt, which range corresponds to a ''high'' Religious Diversity Index (RDI) score?', '5.3 to 6.9', 'The excerpt divides the RDI into ranges and defines ''high'' scores as those from 5.3 to 6.9.', 4),('c97342ac-4bfe-4c7a-8000-c86a25d84db0'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'multiple_choice', 'Which country listed in Table 5.1 is recorded as having 514 languages?', 'Nigeria', 'Table 5.1 in the excerpt lists Nigeria with 514 major languages spoken.', 5),('6ee653d3-744a-4b66-848c-b3d5eba3e66d'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'multiple_choice', 'The excerpt states Africa is home to approximately how many living languages?', 'more than 2000', 'The excerpt explicitly states there are more than 2000 living languages in Africa.', 6),('f98716a3-9b42-4974-83f6-8b7981311cda'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'multiple_choice', 'Which of the following is NOT listed in the excerpt as a way the natural environment supports economic activities?', 'Manufacturing goods', 'The excerpt states the environment supports economic activities directly by providing resources and indirectly via ecosystem services like carbon sequestration and water purification; manufacturing goods is not listed as a direct ecosystem service.', 7),('289ec3f6-7bb6-4411-8ff6-6bbe5ab57118'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'multiple_choice', 'Which of the following is explicitly mentioned in the excerpt as a resource humans obtain from the environment under ''Dependence on the Environment''?', 'Food', 'Under dependence the excerpt lists food as a basic necessity provided by the environment, noting plants and animals as food sources.', 8),('9283dc70-36c0-49da-8a8c-95580084b518'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'multiple_choice', 'Which of the following is given in the excerpt as an example of human modification of the environment?', 'Cutting down forests to increase agricultural land', 'The excerpt lists cutting down forests to increase agricultural land as an example of environmental modification to meet human needs.', 9),('04195d0d-8219-4be5-8c1b-7c2045240c0d'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'multiple_choice', 'Which theory described in the excerpt asserts that the physical environment shapes and creates cultures and controls economic growth?', 'Environmental determinism', 'The excerpt defines environmental determinism as the idea that the physical environment shapes cultures and controls economic activities, a view common in the 19th century.', 10),('3cb09e09-0dfa-41e6-8455-4a5a35f49865'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'multiple_choice', 'Which doctrine in the excerpt claims people can adapt to diverse environmental conditions and choose from many possible responses?', 'Environmental possibilism', 'The excerpt describes environmental possibilism as the doctrine that people can adapt to diverse environmental conditions and choose among many alternatives despite environmental limitations.', 11),('97b5c3d9-dd88-4095-8cc8-402b1768736f'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'multiple_choice', 'According to the excerpt, by how many million did Africa''s population increase between 1500 and 1900?', '20 million', 'The excerpt states Africa''s population increased by only 20 million from 80 million in 1500 to 100 million in 1900.', 12),('b7363308-7bf1-43e9-8c46-ea8a47dc0ec4'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'multiple_choice', 'What average annual population growth rate does the excerpt give for sub-Saharan Africa during the twentieth century (between 1900 and 1980)?', '2.8% per year', 'The excerpt indicates that during the twentieth century sub-Saharan Africa experienced an average population growth of 2.8% per year.', 13),('03349dc5-8a99-4810-8014-dbfc3bcdbbea'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'multiple_choice', 'Which two continents does the excerpt state have each crossed the one billion people milestone?', 'Asia and Africa', 'The excerpt states Asia (about 4.68 billion) and Africa (around 1.37 billion) are the only continents that have crossed one billion people.', 14),('997c20e2-94de-4d37-8c57-24b1fac17077'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'multiple_choice', 'Which SDG in the excerpt focuses specifically on transforming the way cities are built and managed to create sustainable and resilient urban areas?', 'Goal 11', 'The excerpt explains Goal 11 is about sustainable cities and communities and transforming how cities are built and managed to be safe, affordable and resilient.', 15),('3bca61f0-5032-4939-864e-71cea7e26335'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'multiple_choice', 'Which SDG from the excerpt is titled ''Life below water'' and addresses protection of marine and coastal ecosystems?', 'Goal 14', 'The excerpt labels Goal 14 as ''Life below water'', aiming to sustainably manage and protect marine and coastal ecosystems from pollution and other impacts.', 16),('4e9ce07b-2e31-4106-83b0-295a43fa74e7'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'multiple_choice', 'Which SDG in the excerpt is concerned with ''Peace, justice, and strong institutions''?', 'Goal 16', 'The excerpt identifies Goal 16 as addressing peace, stability, human rights and effective governance based on rule of law.', 17),('33a451ae-ea32-4e02-891b-ffd551605463'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'multiple_choice', 'Which example given in the excerpt describes a positive human activity that benefits the environment?', 'Afforestation', 'The excerpt notes humans can have positive effects on the environment, giving afforestation and conservation as examples that improve air quality and protect species.', 18),('42f7fdb8-969d-4e9f-80c5-6a6f1ceb78b7'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'multiple_choice', 'Which subregions are named in the excerpt as representing about 93.5% of the population of the continent in 2015?', 'Eastern, Central, and Western Africa', 'The excerpt states Eastern Africa, Central Africa and Western Africa together represented about 93.5% of the continent''s population in 2015.', 19),('b2e8714a-7d7b-4b76-8809-e004e1b0699c'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'true_false', 'Africa is home to many religions and beliefs.', 'True', 'The excerpt explicitly states Africa is home to many religions and beliefs, containing a mixture of local and global faiths.', 20),('8d2eaa4f-d842-42b8-8b5b-f47d90f07317'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'true_false', 'Africa is the most linguistically diverse continent.', 'True', 'The excerpt states Africa is home to one-third of the world’s 6,000 languages and is therefore the most linguistically diverse continent.', 21),('69873103-a527-4a6c-8b3c-1b69e0d6a705'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'true_false', 'Primary sector involves changing of raw materials into new products.', 'False', 'The review statements in the excerpt indicate that changing raw materials into new products is the secondary sector, not the primary sector which involves extracting raw materials.', 22),('da7f0287-e1d2-4ca9-88bb-90deda3abd9e'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'true_false', 'The excerpt states that the degree of influence of the natural environment declines with increasing modernization and technological advancement.', 'True', 'The excerpt explains possibilism and notes that the natural environment''s influence declines with increasing modernization and technological advancement.', 23),('6d787725-2c05-44aa-88ee-3c497582d7d8'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'fill_blank', 'Define ''population change'' as presented in the excerpt.', 'The difference in the size of the population from the beginning to the end of a certain period.', 'The excerpt defines population change as the difference in size of the population from the beginning to the end of a certain period.', 24),('3a8edfcc-c732-4df7-8217-01aa307898c9'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'fill_blank', 'Name the two factors involved in the increase in the number of individuals in a population according to the excerpt.', 'Fertility (birth) and immigration (in migration).', 'The excerpt states that fertility (birth) and immigration (in migration) are the two factors involved in increasing the number of individuals in a population.', 25),('8dcb4c58-bf15-4430-8c21-6515ba905ded'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'fill_blank', 'List three specific things humans depend on from the environment mentioned in the ''Dependence on the Environment'' section.', 'Food, water, and shelter.', 'The excerpt lists food, water and shelter (also air and clothing) as essential resources humans obtain from the environment.', 26),('c13b19fe-8a15-4c51-8abb-d8227b9a4117'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'fill_blank', 'Give two examples of how humans modify the environment as listed in the excerpt.', 'Cutting down forests to increase agricultural land and construction of dams.', 'The excerpt lists cutting down forests for agriculture and constructing dams to store water for hydroelectricity, irrigation and flood control as examples of modification.', 27),('81f187e4-f141-4b4c-811a-bc7f3d73e660'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'fill_blank', 'What does the Religious Diversity Index (RDI) calculate for countries according to the excerpt?', 'It calculates scores based on the shares of eight major world religions to estimate the number of people who view themselves as belonging to one religious group.', 'The excerpt explains the RDI calculates scores based on shares of eight religious groups to estimate how many people in a country identify with each group, giving an index of diversity.', 28),('bc2f8d40-f318-4959-8ca2-b1fba957f6e2'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'fill_blank', 'Provide a concise definition of environmental determinism as given in the excerpt.', 'The idea that the natural or physical environment shapes and creates cultures and controls economic growth and other human activities.', 'The excerpt defines environmental determinism as the doctrine asserting that the physical environment shapes cultures and controls economic growth and human activities.', 29),('e7aba2e1-ce4b-4f0b-822e-b08cb9a65b65'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'fill_blank', 'Explain environmental possibilism in one sentence using the excerpt''s description.', 'Environmental possibilism is the theory that people can adapt to diverse environmental conditions and choose among many possible responses despite environmental limitations.', 'The excerpt describes possibilism as the doctrine that humans have the capacity to choose between a range of possible responses to environmental constraints and adapt to diverse conditions.', 30),('2c4de880-ed23-4ee4-8f09-a2623b15484c'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'fill_blank', 'Name two indirect ecosystem services listed in the excerpt that benefit humans and the environment.', 'Carbon sequestration and water purification.', 'The excerpt cites carbon sequestration and water purification among the indirect services ecosystems provide, alongside managing flood risks and nutrient cycling.', 31),('a91cbaa6-f3dd-41ac-8e56-efe95d02c275'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'fill_blank', 'According to Table 5.1 in the excerpt, how many languages are spoken in Nigeria?', '514', 'Table 5.1 lists Nigeria with 514 languages spoken, as given in the excerpt''s table of major languages in Africa.', 32),('a1eeea49-425f-4395-871c-1fbae60daa79'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'fill_blank', 'How many languages does Table 5.1 record for Cameroon?', '278', 'The excerpt''s Table 5.1 shows Cameroon as having 278 languages.', 33),('8ce7dc80-2571-4cc2-8cf3-e01d72ff5805'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'fill_blank', 'What RDI score does the excerpt give for Guinea Bissau and Togo?', '7.5', 'The excerpt explicitly states that Guinea Bissau and Togo each have an RDI of 7.5.', 34),('c899f04e-0a41-4066-8382-fc4ae37d4ceb'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'fill_blank', 'What population value for Africa in 2021 is given in Table 6.1 of the excerpt?', '1373486472', 'Table 6.1 in the excerpt lists Africa''s 2021 population as 1373486472.', 35),('4bd7f109-875c-4ce0-8b3e-756d65112e09'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'fill_blank', 'What total world population for 2021 is shown in Table 6.1 of the excerpt?', '7874965732', 'The excerpt''s Table 6.1 gives the 2021 world population total as 7,874,965,732, represented here as 7874965732.', 36),('dc8b4151-2d45-421f-831f-9ae81ab4dcc9'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'fill_blank', 'According to Table 6.1 in the excerpt, what is the net change in world population between 2020 and 2021?', '80167003', 'Table 6.1 lists the net change in the world population for 2021 as 80,167,003, shown here as 80167003.', 37),('1f790ac8-7e1e-4abb-816c-3de161e270c0'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'fill_blank', 'By how many people did Africa''s population increase from 2020 to 2021 according to Table 6.1 in the excerpt?', '32888359', 'Table 6.1 shows Africa''s 2020 population as 1340598113 and 2021 as 1373486472, a net increase of 32,888,359 people as listed (32888359).', 38),('0e10783c-1406-47c1-8685-65e8cc61b27d'::uuid, '6a6a8dce-ab57-4184-8002-3f2c4f573127'::uuid, 'fill_blank', 'What annual growth rate (%) for Oceania in 2021 is reported in Table 6.1 of the excerpt?', '1.27', 'Table 6.1 lists Oceania''s growth net rate for 2021 as 1.27% in the excerpt.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
