INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('44d362af-0de3-407b-8943-c707390c2595'::uuid, 'Geography', 'Unit 7', 'Molarum Grade 10 — Geography Unit 7: Geographic Issues and Public Concerns in Africa', 'Source-grounded Molarum Grade 10 Geography questions for Unit 7: Geographic Issues and Public Concerns in Africa.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('99413a64-8002-4365-8578-992e2f518baa'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'multiple_choice', 'Which of the following best defines urbanization as given in the excerpt?', 'A process by which towns and cities are formed and become larger as more people begin living and working in them', 'The excerpt states urbanization is predominantly the process by which towns and cities are formed and become larger as more people live and work in them, so the first option matches the text.', 0),('d3b87ec0-af73-4f19-8194-982fc906b93e'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'multiple_choice', 'According to the excerpt, unplanned urbanization is considered the root cause of which outcome?', 'Damage to the environment and nature', 'The text states that unplanned urbanization is the root cause of damage to the environment and nature, linking urban expansion to habitat clearing, degradation and pollution.', 1),('0dc55f0d-6ca6-41a0-8d64-619bd9154ce3'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'multiple_choice', 'Which of the following is identified in the excerpt as one of the main factors driving rapid urbanization in Africa?', 'Rural–urban migration driven by the prospect of greater employment opportunities', 'The excerpt explains that one of the main drivers is rural–urban migration motivated by prospects of employment and a better life in cities.', 2),('1402338f-296c-46b1-8adc-057a2604a444'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'multiple_choice', 'Which of the following is listed among the key features of unplanned urbanization in the excerpt?', 'Urban sprawl and compactness', 'The excerpt lists ''Urban sprawl and compactness'' among key features of unplanned urbanization in the Focus box, so this option is correct.', 3),('2bb3f57a-439d-4f68-8805-2e34ad460a33'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'multiple_choice', 'Which of the following is named in the excerpt as a cause of unplanned urbanization in Africa?', 'Weak urban planning institutions', 'The excerpt explicitly lists weak urban planning institutions among the causes of unplanned urbanization in Africa.', 4),('3b479f1f-e755-415f-8dd4-d7cd477bff47'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'multiple_choice', 'Which consequence of unplanned urbanization is described in the excerpt?', 'Development of slums and squatter settlements', 'The text explains that random, unexpected urban growth leads to spread of unlawful residential settlements represented by slums and squatters, making this the correct consequence.', 5),('e1937e44-f047-4ffd-8370-3641b0d8e012'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'multiple_choice', 'Which statement correctly reflects the condition of urban infrastructure in Africa according to the excerpt?', 'Electric power supply and distribution are inadequate', 'The Focus box on urban infrastructure states electric power supply and distribution are inadequate in African urban areas, making this statement correct.', 6),('f7404e46-1f58-4554-834f-2285d6163884'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'multiple_choice', 'According to the excerpt, a benefit of well-managed cities is that they can:', 'Enable economies of scale', 'The excerpt notes that well-managed cities enable economies of scale, which are advantages that can result from increasing the size of an economy or enterprise.', 7),('887893a8-3fb6-4031-8ac7-fb7e6ad1569e'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'multiple_choice', 'What does ''urban primacy'' mean as defined in the excerpt?', 'One city (usually the capital) has population, economic activity and political power several times greater than the next largest city', 'The excerpt defines urban primacy as one city, usually the capital, having population and power several times greater than the next city, so this option matches the text.', 8),('191cdfbe-5f7c-48c0-8928-0a78e8bee0cb'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'multiple_choice', 'Why does unplanned urbanization exacerbate health risks in African cities, according to the excerpt?', 'Because many urban dwellers lack adequate sanitation and high population density fosters disease spread', 'The excerpt explains that lack of adequate sanitation combined with high population density can foster communicable diseases, increasing health risks in unplanned urban areas.', 9),('0d1f8974-72e3-4905-8bb0-c1d65dabcbfc'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'multiple_choice', 'Which combination of processes is emphasised in the excerpt as shaping urbanization in Africa differently from elsewhere?', 'Legacy of colonialism, structural adjustment programs and weak urban planning institutions', 'The excerpt highlights the legacy of colonialism, structural adjustment programs and weak planning institutions as underlying processes that make African urbanization distinctive.', 10),('95dfb22a-f375-4344-8328-4764b5199d19'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'multiple_choice', 'Which factor is given in the excerpt as contributing to the growth of slums and squatter settlements?', 'Lack of developed land for housing', 'The text lists lack of developed land for housing as one of the factors exacerbating the growth of slums and squatter settlements.', 11),('b6bd78d1-b20d-48f2-829e-2cbf69ca3b1a'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'multiple_choice', 'Which transportation statement reflects the excerpt''s description of urban infrastructure in Africa?', 'Transportation infrastructure (roads, railroads, airports, and ports) is very weak', 'The Focus box lists transportation infrastructure as very weak in African urban areas, matching the first option exactly.', 12),('eb44b124-728a-47be-807b-ee7e67c58ee2'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'multiple_choice', 'Which of the following statements about employment in many African urban centres is stated in the excerpt?', 'About 60 percent of jobs are in the informal or grey economy which are neither taxed nor monitored', 'The excerpt notes that about 60 percent of jobs in urban areas are in the informal or grey economy and are neither taxed nor monitored, which makes the first option correct.', 13),('e42912e8-c803-4dc7-8e99-60f081ad3c04'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'multiple_choice', 'According to the earlier adaptation section in the excerpt, adaptation requires which of the following?', 'An adjustment in natural or human systems in response to actual or expected stimuli', 'The adaptation section defines adaptation as an adjustment in natural or human systems in response to actual or expected stimuli, so the first option restates that definition.', 14),('a2900147-4fa9-4de1-887f-0ac81c9eebea'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'multiple_choice', 'Which description matches ''planned adaptation'' as given in the adaptation section of the excerpt?', 'An adaptation resulting from a deliberate policy decision based on awareness that conditions have changed or are about to change', 'The excerpt defines planned adaptation as the result of a deliberate policy decision based on awareness that conditions have changed or will change, which matches the correct option.', 15),('e7686634-fd50-447c-8e14-7340813ae86f'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'multiple_choice', 'Which example in the excerpt illustrates an ecosystem-based (green) adaptation option?', 'Reforestation to stop desertification and recharge groundwater in droughts', 'The excerpt gives reforestation as an example of a green, ecosystem-based adaptation that can stop desertification and help recharge groundwater supplies during drought.', 16),('9f3ede18-e955-4de8-8246-da523156f25f'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'multiple_choice', 'What is the primary aim of green and soft adaptation measures according to the excerpt?', 'Decreasing sensitivity and increasing adaptive capacity of human and natural systems', 'The text explains that green and soft measures aim at decreasing sensitivity and increasing adaptive capacity of systems, thereby building resilience, which matches the first option.', 17),('5d5947a8-a30e-4e50-8263-418aab7637dd'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'multiple_choice', 'Which of the following is NOT listed in the excerpt as a part of the adaptation process?', 'Commercial exploitation of conserved sacred sites for tourism without rules', 'The excerpt lists analysis, strategy design and implementation, monitoring and evaluation, and sharing lessons as parts of adaptation; commercial exploitation without rules is not listed and would contradict conservation aims.', 18),('eb78d96a-e4ab-4f88-836f-5afc158f0604'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'multiple_choice', 'Which statement correctly describes planned adaptation as defined in the excerpt?', 'It is a deliberate policy decision based on awareness that conditions have changed or are about to change and that action is required', 'The excerpt defines planned adaptation precisely as a deliberate policy decision made because of awareness of changing conditions and the need for action, matching the correct option.', 19),('329bc62f-767d-49ab-832e-340b0a005a02'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'true_false', 'Urbanization refers to the population shift from rural to urban areas.', 'True', 'The excerpt defines urbanization as a population shift from rural to urban areas, so the statement is true.', 20),('b6e64d9b-a123-4d50-8272-4a0ae8c37592'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'true_false', 'Urbanization denotes only the growth of the physical area of towns and not the growth of population living there.', 'False', 'The excerpt states urbanization includes both growth of the area of towns and the growth of population living there, so the statement is false.', 21),('3640a94e-1f93-40b1-8056-f4ee3e9abb74'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'true_false', 'Africa''s urban population is expected to reach 2.5 billion in 2050 according to the excerpt.', 'True', 'The excerpt explicitly states Africa’s urban population is expected to reach 2.5 billion in 2050, making the statement true.', 22),('c7bb6276-0de4-4322-8e12-b16e58e84c02'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'true_false', 'According to the excerpt, a megacity is defined as a city with population over 5 million.', 'False', 'The excerpt defines megacities as cities with populations over 10 million, not 5 million, so the statement is false.', 23),('94fa7e52-0002-4c8b-86fc-02a504870b19'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'fill_blank', 'Convert the excerpt''s figure ''2.5 billion'' (Africa''s expected urban population in 2050) into millions.', '2500 million', '2.5 billion equals 2.5 × 1,000 million = 2500 million, using the numeric relationship given in the excerpt.', 24),('6e755bb1-64c5-4e98-8570-e3fdacd4963f'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'fill_blank', 'How many megacities in Africa are named in the excerpt (cities with populations over 10 million)?', '7', 'The excerpt lists seven megacities (Cairo, Kinshasa, Lagos, Accra, Johannesburg–Pretoria, Khartoum, and Nairobi), so the number is seven.', 25),('74e3b6fa-d55a-4fc4-8f09-db496058b227'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'fill_blank', 'If about 60 percent of jobs are in the informal or grey economy as stated in the excerpt, what percent of jobs are not in the informal or grey economy?', '40%', 'If about 60% are informal, the remainder not in the informal or grey economy is 100% − 60% = 40%, as implied by the excerpt''s percentage.', 26),('31c66002-7281-4436-8eb9-a135de91f4f4'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'fill_blank', 'Express the excerpt''s figure ''21%'' (Africa''s share of the world''s projected urban population) as a decimal.', '0.21', '21 percent expressed as a decimal is 21 ÷ 100 = 0.21, directly converting the percentage given in the excerpt.', 27),('c7b5bcf9-e34c-4977-8bbd-b3e25186cf51'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'fill_blank', 'The excerpt states Africa''s urban population is expected to reach 2.5 billion in 2050 and that this accounts for 21% of the world''s projected urban population; calculate the world''s projected urban population (in billions) implied by these figures. Give your answer rounded to one decimal place.', '11.9 billion', 'If 2.5 billion represents 21% of the world''s projected urban population, world = 2.5 ÷ 0.21 ≈ 11.9048 billion, rounded to one decimal place is 11.9 billion, following the relationship given in the excerpt.', 28),('2f13552c-1df3-48de-81eb-4cf120a93b9e'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'fill_blank', 'The excerpt states there are seven megacities, defined as cities with populations over 10 million. What is the minimum possible combined population (in millions) of these seven megacities, using the threshold given?', '70 million', 'If each megacity has at least 10 million people, the minimum combined population is 7 × 10 million = 70 million, using the threshold provided in the excerpt.', 29),('c75b2641-e2c8-4267-8bf9-df36dddd0c64'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'fill_blank', 'Using the excerpt''s statement that about 60 percent of jobs are in the informal economy, express the ratio of informal to formal jobs in simplest whole-number form.', '3:2', 'If 60% are informal and 40% are formal, the ratio informal:formal is 60:40 which simplifies by dividing by 20 to 3:2, using the percentages given in the excerpt.', 30),('0a4e01a9-3ba2-4410-80ea-bf54b60de38e'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'fill_blank', 'In the Teso community case study presented, remains were exhumed from graves that were at least how many years old?', '10 years', 'The case study specifies graves had to be at least ten years old before exhumation, so the minimum age is 10 years as stated in the excerpt.', 31),('5627e423-9712-4143-88cf-2f876870659e'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'fill_blank', 'Define ''unplanned urbanization'' as described in the excerpt.', 'Unplanned urbanization is urban expansion and population growth that occur in an unregulated, random or unexpected way, leading to environmental damage and inadequate services.', 'The excerpt explains unplanned urbanization involves unregulated growth that damages the environment and outpaces planning and infrastructure, which the answer summarizes.', 32),('0c7799c9-b8c3-41a8-8cff-1f52de7bbf60'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'fill_blank', 'Provide the definition of ''migration'' given in the excerpt.', 'Migration is the movement of people from one place to another to establish permanent or semi-permanent residence at the destination.', 'The excerpt defines migration as movement of people to establish permanent or semi-permanent residence at a destination, which the answer restates.', 33),('6445a782-fae9-49d6-84ed-2f4d368e28a2'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'fill_blank', 'In your own words, define ''urban primacy'' as used in the excerpt.', 'Urban primacy is the condition where one city, usually the capital, has population, economic activity and political power several times greater than the next largest city.', 'The excerpt defines urban primacy exactly as one dominant city far larger in population and power than the next city, which the answer reflects.', 34),('660ac73c-c553-4027-85f2-766357a653df'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'fill_blank', 'Define ''slum'' or ''squatter settlement'' as described in the excerpt.', 'A slum or squatter settlement is an unlawful residential area that develops from random, unexpected urban growth where residents lack adequate services and secure land tenure.', 'The excerpt describes slums and squatters as unlawful residential settlements arising from unplanned growth, often with poor services and tenure insecurity, which the answer summarizes.', 35),('b1a1166e-98e8-4287-82ff-98e4a1973f8c'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'fill_blank', 'List the causes of unplanned urbanization in Africa cited in the excerpt (give up to five).', 'Unplanned and unregulated growth; the legacy of colonialism; structural adjustment programs of international institutions (e.g., IMF); pressure from developed countries (neoliberal policies); weak urban planning institutions.', 'The Focus box in the excerpt lists these specific causes of unplanned urbanization in Africa, so the answer enumerates them as stated.', 36),('c9109907-68ab-408f-8ec5-95b49e19f3be'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'fill_blank', 'Name two consequences of unplanned urbanization discussed in the excerpt.', 'Development of slums and squatter settlements; poor infrastructure and insufficient water supply and sewage.', 'The excerpt discusses multiple consequences including slums and poor infrastructure (water supply and sewage shortages), so the answer gives two of these consequences as examples.', 37),('8d473a39-cf5d-47a0-89b4-4d87f3a77472'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'fill_blank', 'Give two characteristics of urban infrastructure in Africa mentioned in the excerpt.', 'Transportation infrastructure is very weak; water supply and sewage are in serious shortage.', 'The Focus box on urban infrastructure lists weak transportation systems and serious shortages in water supply and sewage as characteristics, which the answer cites.', 38),('b78f908c-bcbc-459e-8022-6988690ed071'::uuid, '44d362af-0de3-407b-8943-c707390c2595'::uuid, 'fill_blank', 'According to the adaptation section in the excerpt, what do well-planned adaptation strategies result in?', 'They result in adaptation responses which are implementation actions to respond to environmental impacts that have already occurred as well as future impacts.', 'The excerpt states that well-planned adaptation strategies result in adaptation responses, meaning actions implemented to address past and future environmental impacts, which the answer restates.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
INSERT INTO public.choices (id, question_id, choice_text, is_correct, order_index) VALUES ('cb471eb9-6c97-4b38-8f23-eb543c7204ff'::uuid, '99413a64-8002-4365-8578-992e2f518baa'::uuid, 'A process by which towns and cities are formed and become larger as more people begin living and working in them', TRUE, 0),('b2b0db79-0811-44a8-8615-fe25205d9a4e'::uuid, '99413a64-8002-4365-8578-992e2f518baa'::uuid, 'An increase in agricultural production in rural areas', FALSE, 1),('ddfa8f87-cdcf-423b-8da2-89c938ca704a'::uuid, '99413a64-8002-4365-8578-992e2f518baa'::uuid, 'A decline in the population of towns and cities', FALSE, 2),('87b1f355-6cf8-4baf-85bf-ac6555cffad1'::uuid, '99413a64-8002-4365-8578-992e2f518baa'::uuid, 'A government program to build roads in rural areas', FALSE, 3),('fda071f8-282a-44d4-84aa-ea0834429450'::uuid, 'd3b87ec0-af73-4f19-8194-982fc906b93e'::uuid, 'Damage to the environment and nature', TRUE, 0),('f87e79d1-511d-40d6-8eb9-05f37296c43d'::uuid, 'd3b87ec0-af73-4f19-8194-982fc906b93e'::uuid, 'Improved soil fertility across rural areas', FALSE, 1),('b61412d5-e814-4e7b-8739-c2c0f0db8e63'::uuid, 'd3b87ec0-af73-4f19-8194-982fc906b93e'::uuid, 'Decrease in waste generation', FALSE, 2),('82da82bd-3248-41c6-8109-61053e778b49'::uuid, 'd3b87ec0-af73-4f19-8194-982fc906b93e'::uuid, 'Expansion of pristine forest cover', FALSE, 3),('a46b25ff-bb57-4951-80a6-86e0376d373b'::uuid, '0dc55f0d-6ca6-41a0-8d64-619bd9154ce3'::uuid, 'Rural–urban migration driven by the prospect of greater employment opportunities', TRUE, 0),('7198aa23-a132-4873-8aab-eec89badd744'::uuid, '0dc55f0d-6ca6-41a0-8d64-619bd9154ce3'::uuid, 'A global decline in birth rates only in cities', FALSE, 1),('7bd534df-a7cd-4b42-8e09-5b7d2279b035'::uuid, '0dc55f0d-6ca6-41a0-8d64-619bd9154ce3'::uuid, 'Mandatory relocation programs by every rural community', FALSE, 2),('9f20af40-0a86-4811-8564-a2e1e6ed67b6'::uuid, '0dc55f0d-6ca6-41a0-8d64-619bd9154ce3'::uuid, 'An international ban on rural farming', FALSE, 3),('9733730c