transportation infrastructure is modern and robust', FALSE, 1),('d0324ac9-38b6-4519-8190-06ef7a03bcda'::uuid, 'e1937e44-f047-4ffd-8370-3641b0d8e012'::uuid, 'Water supply and sewage are universally adequate', FALSE, 2),('e7b38e23-b99d-42b7-8299-51b8857420c8'::uuid, 'e1937e44-f047-4ffd-8370-3641b0d8e012'::uuid, 'Communications infrastructure is highly advanced across the continent', FALSE, 3),('ab4db6d5-cc1c-470a-8f25-083d70c79041'::uuid, 'f7404e46-1f58-4554-834f-2285d6163884'::uuid, 'Enable economies of scale', TRUE, 0),('95122b3f-51c8-4eb4-8080-d4a4b1d91b23'::uuid, 'f7404e46-1f58-4554-834f-2285d6163884'::uuid, 'Eliminate the need for any planning', FALSE, 1),('a2c54179-b83f-4333-86e8-89eadac74da8'::uuid, 'f7404e46-1f58-4554-834f-2285d6163884'::uuid, 'Reduce population density to zero', FALSE, 2),('b19dbd2c-9093-41d8-82e2-213215884a78'::uuid, 'f7404e46-1f58-4554-834f-2285d6163884'::uuid, 'Make rural areas obsolete', FALSE, 3),('f0f82786-b472-4360-86e9-b82ba0c78781'::uuid, '887893a8-3fb6-4031-8ac7-fb7e6ad1569e'::uuid, 'One city (usually the capital) has population, economic activity and political power several times greater than the next largest city', TRUE, 0),('06718ad1-99e4-41c5-80b6-ee6d420094e4'::uuid, '887893a8-3fb6-4031-8ac7-fb7e6ad1569e'::uuid, 'All cities in a country have equal population and power', FALSE, 1),('c567d12f-aec1-482f-870c-79f94b3fb21f'::uuid, '887893a8-3fb6-4031-8ac7-fb7e6ad1569e'::uuid, 'A strict ban on migration to secondary cities', FALSE, 2),('ffb8d57d-213c-4028-8c5f-cc9696d076ea'::uuid, '887893a8-3fb6-4031-8ac7-fb7e6ad1569e'::uuid, 'A policy to decentralize services to all towns', FALSE, 3),('0b6e1c4d-f480-4b28-8863-c1bd0ddd2360'::uuid, '191cdfbe-5f7c-48c0-8928-0a78e8bee0cb'::uuid, 'Because many urban dwellers lack adequate sanitation and high population density fosters disease spread', TRUE, 0),('f1a73d44-23c9-4551-8eaf-a641e8666aa3'::uuid, '191cdfbe-5f7c-48c0-8928-0a78e8bee0cb'::uuid, 'Because cities remove all green spaces which produce