'20247453-0156-4f5d-8df0-9fa3db6d80ba'::uuid, 'a2900147-4fa9-4de1-887f-0ac81c9eebea'::uuid, 'A process of immediate spontaneous migration only', FALSE, 2),('0a4db761-bcdf-4008-81a1-d3baffdd2538'::uuid, 'a2900147-4fa9-4de1-887f-0ac81c9eebea'::uuid, 'A practice that never involves policy or planning', FALSE, 3),('f046e485-6b5d-4115-8dae-281a394adc25'::uuid, 'e7686634-fd50-447c-8e14-7340813ae86f'::uuid, 'Reforestation to stop desertification and recharge groundwater in droughts', TRUE, 0),('aa0b6a34-33a6-453f-8d04-3740dd53b40f'::uuid, 'e7686634-fd50-447c-8e14-7340813ae86f'::uuid, 'Building large-scale desalination plants powered by fossil fuels', FALSE, 1),('e56a1d54-3b98-4a35-80f3-cc5c410b10c8'::uuid, 'e7686634-fd50-447c-8e14-7340813ae86f'::uuid, 'Importing foreign food supplies', FALSE, 2),('27208e18-041f-4c89-8e2f-81f442be3d54'::uuid, 'e7686634-fd50-447c-8e14-7340813ae86f'::uuid, 'Constructing tall concrete seawalls without vegetation', FALSE, 3),('5f96c905-6130-4dbf-88fb-14a3029939a5'::uuid, '9f3ede18-e955-4de8-8246-da523156f25f'::uuid, 'Decreasing sensitivity and increasing adaptive capacity of human and natural systems', TRUE, 0),('227735f3-2b00-4e63-888b-35da6f3ab244'::uuid, '9f3ede18-e955-4de8-8246-da523156f25f'::uuid, 'Maximizing immediate economic profit regardless of environment', FALSE, 1),('a04a9e22-d252-4a35-832f-04b07b7a13ee'::uuid, '9f3ede18-e955-4de8-8246-da523156f25f'::uuid, 'Eliminating all forms of indigenous knowledge', FALSE, 2),('38e892e4-def2-47ba-82a5-c6def976395f'::uuid, '9f3ede18-e955-4de8-8246-da523156f25f'::uuid, 'Requiring only high amounts of funding and advanced technology', FALSE, 3),('105f2264-2a20-43a2-8e73-bb65a78d2658'::uuid, '5d5947a8-a30e-4e50-8263-418aab7637dd'::uuid, 'Commercial exploitation of conserved sacred sites for tourism without rules', TRUE, 0),('20abc579-8cf8-4d14-8d9b-d6a72c7bfcae'::uuid, '5d5947a8-a30e-4e50-8263-418aab7637dd'::uuid, 'Analysis of current exposure to shocks and stresses', FALSE, 1),('759ee88b-816d-4359-88f9-20d89a68621a'::uuid, '5d5947a8-a30e-4e50-8263-418aab7637dd'::uuid, 'Design and implementation of adaptation strategies', FALSE, 2),('e64cee7a-7546-48eb-88ea-ac169ce8a825'::uuid, '5d5947a8-a30e-4e50-8263-418aab7637dd'::uuid, 'Monitoring and evaluation of planned activities', FALSE, 3),('69a702e1-abb8-449a-8f33-b5b3acc518ea'::uuid, 'eb78d96a-e4ab-4f88-836f-5afc158f0604'::uuid, 'It is a deliberate policy decision based on awareness that conditions have changed or are about to change and that action is required', TRUE, 0),('ba5c48e6-f066-4de2-8dca-ff23bda9ce82'::uuid, 'eb78d96a-e4ab-4f88-836f-5afc158f0604'::uuid, 'It is always spontaneous with no policy involvement', FALSE, 1),('863aa09b-1d5f-4edf-8236-605bec6d0a73'::uuid, 'eb78d96a-e4ab-4f88-836f-5afc158f0604'::uuid, 'It never requires monitoring and evaluation', FALSE, 2),('44b4b138-e02b-4a49-889b-225d872a8c81'::uuid, 'eb78d96a-e4ab-4f88-836f-5afc158f0604'::uuid, 'It is defined as only technological high-cost solutions', FALSE, 3),('027a2d5a-264f-4a1c-8f10-2f12b6a96f4a'::uuid, '329bc62f-767d-49ab-832e-340b0a005a02'::uuid, 'True', TRUE, 0),('f074cbe8-e223-41fd-8143-b9a9fe288272'::uuid, '329bc62f-767d-49ab-832e-340b0a005a02'::uuid, 'False', FALSE, 1),('bdb0ae62-82bd-4017-8d0e-d4b7d36d33ff'::uuid, 'b6e64d9b-a123-4d50-8272-4a0ae8c37592'::uuid, 'True', FALSE, 0),('b5d4e024-3be9-44e5-8a33-e888f9181202'::uuid, 'b6e64d9b-a123-4d50-8272-4a0ae8c37592'::uuid, 'False', TRUE, 1),('842c5688-2ff4-475a-89f1-054f3a9e669b'::uuid, '3640a94e-1f93-40b1-8056-f4ee3e9abb74'::uuid, 'True', TRUE, 0),('e253ed0d-e0be-4167-8db1-704d3f493d88'::uuid, '3640a94e-1f93-40b1-8056-f4ee3e9abb74'::uuid, 'False', FALSE, 1),('d54654da-66ad-40f3-8c21-577410806157'::uuid, 'c7bb6276-0de4-4322-8e12-b16e58e84c02'::uuid, 'True', FALSE, 0),('ceaddbe5-4b02-4f43-868f-dc45d2eb55b8'::uuid, 'c7bb6276-0de4-4322-8e12-b16e58e84c02'::uuid, 'False', TRUE, 1) ON CONFLICT (id) DO UPDATE SET question_id = EXCLUDED.question_id, choice_text = EXCLUDED.choice_text, is_correct = EXCLUDED.is_correct, order_index = EXCLUDED.order_index;
INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'Geography', 'Unit 8', 'Molarum Grade 10 — Geography Unit 8: Geospatial Information and Data Processing', 'Source-grounded Molarum Grade 10 Geography questions for Unit 8: Geospatial Information and Data Processing.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('e109bb43-1e68-44cd-8961-138091af1191'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Which of the following statements about data is CORRECT according to the unit?', 'Data is used as an input for the computer system.', 'The unit states that data are unprocessed facts used as input to computer systems, whereas information is the processed output derived from data.', 0),('4438a03d-8e19-4b7c-8353-86733dc29c76'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Which of the following is NOT listed as a stage in the data lifecycle in the unit?', 'Data manufacturing', 'The unit lists collection, processing (QA/QC), analysis and dissemination as stages; ''data manufacturing'' is not mentioned.', 1),('d00a1013-995d-4197-8267-eadad2d52705'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'According to the unit, a GPS receiver must connect with how many satellites to calculate a precise location?', 'Four or more satellites', 'The text states a GPS receiver needs to connect with four or more satellites to calculate the precise location within a few meters.', 2),('35bdcce0-bf39-40b4-806f-a672b6e9cf6e'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'What is the primary purpose of a digitizer as described in the unit?', 'To change images on an analogue form or paper into a digital form on a computer.', 'The unit defines a digitizer as the tool that converts analogue paper images into digital, computer-readable formats.', 3),('6b4889f4-fc88-4d13-8f0c-82a3fb673b3f'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Which of the following is given in the unit as an example of directly collected geographic data?', 'Temperature readings at specific weather stations', 'The unit states directly collected data include measurements at the source such as temperature readings at weather stations, while satellite images and aerial photos are remotely sensed.', 4),('980f4c50-40b7-4835-8d90-b64e63d482dc'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Which of the following terms does the unit NOT list among the key terms in section 8.1?', 'Topography', 'The unit''s key term list includes Attribute, Continuous data and Temporal information but does not list ''Topography''.', 5),('b9154b44-6e9d-4b28-80dd-77dbf68fb07b'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Why does the unit say ''place'' or location is essential when collecting geographical data?', 'Because locations are the basis for mapping and allow linking information and measuring distances and areas.', 'The unit explains place is essential because locations form the basis for mapping, linking different information and measuring distances and areas.', 6),('faba4cc1-057b-42d5-89a8-f4760326e799'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'The unit describes ''time'' in geospatial data as:', 'An optional element because some surface features change slowly and time can often be omitted.', 'The text states time is optional since many surface features change very slowly and can be omitted for many applications.', 7),('77e1365e-49df-4d6a-87c6-80209973c59d'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Which of the following is given in the unit as an example of a discrete object in geographic data?', 'Lake', 'The unit uses a lake as an example of a discrete object with well-defined boundaries, whereas elevation and temperature are continuous.', 8),('b981d23f-d97d-49f6-8867-a1c1ba0cea39'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Which of the following does the unit list as an example of continuous (field) data?', 'Elevation', 'The unit gives elevation as an example of continuous data that varies progressively across a surface.', 9),('b2e87ccb-bb9d-496c-8015-cbff20acb50e'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'The unit states there are two fundamental ways of visualizing geographic data. Which of the following is NOT one of them?', 'Categorical clustering', 'The text names discrete objects and continuous data as the two fundamental visualization ways; ''categorical clustering'' is not listed.', 10),('e21908ec-5da3-4073-8f3c-870542c89c93'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Which of the following is listed in the unit as a common general source for geographic data?', 'Hard copy maps (analogue maps)', 'The unit lists hard copy (analogue) maps among the most common general sources for geographic data; the other options are not listed.', 11),('d7f7c578-2413-481c-8a81-1b6f8c6050e2'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Which product does the unit say a GPS receiver provides that is valuable for documenting information about a place?', 'Latitudinal and longitudinal coordinate values and elevation', 'The unit explains GPS receivers provide latitudinal and longitudinal coordinates and elevation values useful for documenting places.', 12),('5162eea8-921f-41ba-80fd-f57f5f2dd999'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'According to the unit, which statement about outputs of digitizers and scanners is TRUE?', 'Data generated by digitizers provides geo-referenced information, while images from scanners should be geo-referenced.', 'The text states digitizers yield geo-referenced data, whereas scanner images should be geo-referenced to relate internal coordinates to geographic coordinates.', 13),('b130ac39-ddba-4c8c-80cd-018ba54f4505'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Which advantage of digital geographic data over hardcopy does the unit explicitly mention?', 'Digital data are easy to copy and transmit at very high speeds.', 'The unit lists that digital data are easy to copy and transmit quickly, and are easier to transform, process and analyze compared to hardcopy.', 14),('967e76ca-5bda-491f-8149-10dd2d91f5ae'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'A map is composed of geographic features represented in which basic forms, according to the unit?', 'Points, lines and/or areas (polygons)', 'The unit states maps model real-world features as points, lines and areas, each defined by location and attributes.', 15),('b3c5ce7d-93f8-4d28-81a2-678d523ade80'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'In the vector data model described in the unit, what is a ''node''?', 'A vertex that starts or ends an arc segment', 'The unit defines a node as a vertex that starts or ends an arc (line) segment in vector storage.', 16),('59e5a741-8a37-4b7d-8a06-61d7e6bef8b7'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'How does the unit say raster data represent area (polygonal) features?', 'By collections of contiguous cells', 'The text explains raster represents areas by collections of contiguous grid cells; points by single cells and lines by sequences of neighboring cells.', 17),('6d0fdd5a-1c14-489a-8718-fa458f771951'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Which of the following is identified in the unit as a component of GIS?', 'Hardware', 'The unit lists hardware (computers and peripheral devices) as one of the GIS components.', 18),('2f643454-2fa8-45cd-8bae-f4087db53ccb'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Which historical advance does the unit credit with helping mapmakers locate precise positions on Earth?', 'Dividing the Earth into lines of longitude and latitude', 'The unit notes that advances in mathematics and astronomy and dividing Earth into longitude and latitude were notable for improving map accuracy.', 19),('826490a3-6eeb-4fe1-8c1b-112a98aa7e2f'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'true_false', 'Time is always required when representing geographical data according to the unit.', 'False', 'The unit explicitly states time is optional because many surface features change slowly and time can often be omitted.', 20),('970a2275-43b6-454d-8ec1-bb789ae32356'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'true_false', 'Remotely sensed data are measured without direct contact with the phenomena or a need to visit locations of interest.', 'True', 'The unit defines remotely sensed data as measured from remote distances without direct contact or visiting the location of interest.', 21),('76551550-3dd5-4bb6-81fc-658b31adc364'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'true_false', 'The unit states that digital geographic data are easy to transform, process and analyze compared to hardcopy.', 'True', 'The text lists ease of transformation, processing and analysis as advantages of digital formats over hardcopy.', 22),('7ac53e8e-49b1-46ce-85db-54dcb68fa81d'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'true_false', 'In the vector data model a point feature is defined by one coordinate pair of X and Y.', 'True', 'The unit states that a point feature is defined by one coordinate pair (X and Y) in the vector model.', 23),('41a226d1-15ab-4e4f-837e-043cd714277e'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'Define geospatial data as described in the unit.', 'Data about objects, events or phenomena that include location information and often attribute and temporal information.', 'The unit defines geospatial data as data about phenomena that have location (coordinates) and attribute (and optionally temporal) information representing the Earth''s surface.', 24),('556f98b0-7cca-487f-85e1-8b78e4e7d378'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'Name the two most important tools for geographic data collection highlighted in the unit.', 'Global Positioning System (GPS) and digitizers.', 'The unit explicitly names GPS and digitizers as the two most important tools or hardware for collecting geographic data.', 25),('a279fe05-25f6-4bf2-8719-c50e7cb5ccd4'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'List the four primary stages of the data lifecycle described in the unit.', 'Data collection, data processing (QA/QC), data analysis, and dissemination (including archiving).', 'The unit outlines a lifecycle that begins with collection, moves to processing (QA/QC), then analysis, and ends with dissemination and archiving for future use.', 26),('94fe1a56-b153-4f29-8a5c-43485688ffe0'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'Give one example each of a directly collected source and a remotely sensed source as given in the unit.', 'Directly collected: temperature readings at a weather station; Remotely sensed: satellite images.', 'The unit gives temperature readings at specific stations as directly collected data and satellite images as remotely sensed data.', 27),('baecb721-a7f3-42bf-80d7-3b701482a876'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'What are the three basic geographic feature types used to represent real-world features on maps?', 'Point, line and area (polygon).', 'The unit states that geographic features on maps are characterized as points, lines or areas (polygons), each defined by location and attributes.', 28),('3b7f2de4-9bca-4610-8376-fd2412fed2e0'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'Briefly define a raster data model as described in the unit.', 'A grid-cell data structure dividing the area into cells (rows and columns) where attributes are assigned to cells.', 'The unit explains raster uses a tessellated grid of cells identified by row and column, with each cell classified by its most common attribute.', 29),('65bf1afa-a6e6-48c0-8eff-e843b9e45b3f'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'Briefly define the vector data model as described in the unit.', 'A storage method using sequential points or vertices (X,Y pairs) to define points, lines (arcs) and closed coordinate pairs for polygons.', 'The unit describes vector storage as using sequential vertices (X and Y coordinates) to represent points, lines (arcs) and polygonal features.', 30),('cbceac12-c976-4c53-8390-f811a6e3278b'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'What does georeferencing mean based on the unit''s explanation?', 'Relating the internal coordinate system of a map or image to a geographic coordinate system of the area being scanned.', 'The unit defines georeferencing as linking a map or aerial photo''s internal coordinates to a geographic coordinate system so location relates to real-world coordinates.', 31),('6ca02491-15bb-4fc3-88aa-6c7e4b1f3f09'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'What is the minimum number of satellites a GPS receiver needs to connect with to calculate the precise location, as stated in the unit?', '4', 'The unit specifies a GPS receiver needs to connect with four or more satellites; the minimum number given is four.', 32),('fbedb200-8840-4a16-8959-911f09134360'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'According to the UNEP figure quoted in the unit, approximately how many tons of plastic were produced globally in 2020?', 'Over 400 million tons', 'The unit quotes UNEP''s estimate that total global plastic production in 2020 was over 400 million tons.', 33),('e959f634-241f-4cab-8674-9364a96c14d6'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'What percentage of global plastic production in 2020 was produced in China according to the unit?', '28%', 'The unit states China accounted for 28% of global plastic production in 2020 according to UNEP.', 34),('867aaf7b-306a-4f36-89b6-f48f93ec812f'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'How many people were reported living in Africa as of 2020 in the unit?', '1.3 billion', 'The unit reports that 1.3 billion people were living in Africa in 2020, representing 16% of the world''s population.', 35),('7f59fca0-fecc-4273-8c00-80a8b51f72c1'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'What percentage of global plastic volumes did Africa produce according to the unit?', '5%', 'The unit states Africa produced 5% of global plastic volumes in 2020.', 36),('ba7a781a-b777-4a72-8f89-55b3c2a9b0c4'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'What was the plastic consumption in Africa in 2015 per person according to the unit (kg per person)?', '16 kg', 'The unit reports plastic consumption in Africa in 2015 was 16 kg per person.', 37),('8086cd50-4b22-432a-8a5f-529ef66fdf8e'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'What was the global average plastic consumption per person cited in the unit (kg per person)?', '45 kg', 'The unit gives the global average plastic consumption in 2015 as 45 kg per person.', 38),('aa5269c7-0f82-42ac-8086-d68a91c6d686'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'According to the unit, what percentage of plastic is recycled in South Africa and approximately how many metric tons of discarded plastic end up in rivers?', '16% recycled; about 8 million metric tons discarded', 'The unit states in South Africa 16% of plastic is recycled and the remaining (about 8 million metric tons) is discarded and ends up in rivers.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
INSERT INTO public.choices (id, question_id, choice_text, is_correct, order_index) VALUES ('bb53aa2b-16ff-4a68-8f52-52b47ba3eb65'::uuid, 'e109bb43-1e68-44cd-8961-138091af1191'::uuid, 'Data is used as an input for the computer system.', TRUE, 0),('ed7549bf-4e98-4745-8070-c93df7467654'::uuid, 'e109bb43-1e68-44cd-8961-138091af1191'::uuid, 'Information is used as an input for the computer system.', FALSE, 1),('93ff62ab-b561-41c3-8e9b-0a23c5ae25d1'::uuid, 'e109bb43-1e68-44cd-8961-138091af1191'::uuid, 'Data is the processed output of a computer system.', FALSE, 2),('9ddb4d9a-cd14-4d57-85cb-a7ec72bcdbb3'::uuid, 'e109bb43-1e68-44cd-8961-138091af1191'::uuid, 'Information does not depend on data.', FALSE, 3),('0e7aefb7-4c90-4741-8590-9bbe4038cf6f'::uuid, '4438a03d-8e19-4b7c-8353-86733dc29c76'::uuid, 'Data collection', FALSE, 0),('88c1418c-4850-4d65-853c-9109148e29bc'::uuid, '4438a03d-8e19-4b7c-8353-86733dc29c76'::uuid, 'Data processing', FALSE, 1),('909142e5-1e61-4696-8c9f-16b06e969220'::uuid, '4438a03d-8e19-4b7c-8353-86733dc29c76'::uuid, 'Data manufacturing', TRUE, 2),('f50f8b24-9529-481c-8090-dbe21ad93d89'::uuid, '4438a03d-8e19-4b7c-8353-86733dc29c76'::uuid, 'Data dissemination', FALSE, 3),('205f7b18-ea4c-4d18-8183-d872a8277600'::uuid, 'd00a1013-995d-4197-8267-eadad2d52705'::uuid, 'Two satellites', FALSE, 0),('3557d3d6-d97b-4ea3-8846-4e166bbbfef9'::uuid, 'd00a1013-995d-4197-8267-eadad2d52705'::uuid, 'Three satellites', FALSE, 1),('2fca5d9c-99b7-43b4-84cb-b3420a94a399'::uuid, 'd00a1013-995d-4197-8267-eadad2d52705'::uuid, 'Four or more satellites', TRUE, 2),('320ce40e-259d-43ec-89db-c4f45f99a10f'::uuid, 'd00a1013-995d-4197-8267-eadad2d52705'::uuid, 'Ten satellites', FALSE, 3),('e06dbadc-43c0-45e0-8c1c-a0890edb1976'::uuid, '35bdcce0-bf39-40b4-806f-a672b6e9cf6e'::uuid, 'To change images on an analogue form or paper into a digital form on a computer.', TRUE, 0),('02852c70-c892-4152-8c26-f8e776bf0228'::uuid, '35bdcce0-bf39-40b4-806f-a672b6e9cf6e'::uuid, 'To measure temperature at a weather station.', FALSE, 1),('2d9a6d03-c5b3-455c-820e-aaf8643578ef'::uuid, '35bdcce0-bf39-40b4-806f-a672b6e9cf6e'::uuid, 'To orbit the Earth and capture satellite imagery.', FALSE, 2),('34e58ad2-ce03-4f8d-80f1-4220b899f968'::uuid, '35bdcce0-bf39-40b4-806f-a672b6e9cf6e'::uuid, 'To pump water for field surveys.', FALSE, 3),('73b4f555-3ace-4c06-8b3f-dfbf3306b7d8'::uuid, '6b4889f4-fc88-4d13-8f0c-82a3fb673b3f'::uuid, 'Temperature readings at specific weather stations', TRUE, 0),('98ff05c1-3949-4374-8677-9c75b30b9b43'::uuid, '6b4889f4-fc88-4d13-8f0c-82a3fb673b3f'::uuid, 'Satellite images', FALSE, 1),('c087c56e-ba02-4417-8072-57da4ba023f9'::uuid, '6b4889f4-fc88-4d13-8f0c-82a3fb673b3f'::uuid, 'Aerial photographs', FALSE, 2),('b2a7f436-0cb0-4d7c-8bb9-10055f598da4'::uuid, '6b4889f4-fc88-4d13-8f0c-82a3fb673b3f'::uuid, 'Existing digital data files', FALSE, 3),('e202d7b7-5214-49c9-88d3-57edb0833ec2'::uuid, '980f4c50-40b7-4835-8d90-b64e63d482dc'::uuid, 'Attribute', FALSE, 0),('3f29f00e-98c7-4293-80b3-69626f4e6b23'::uuid, '980f4c50-40b7-4835-8d90-b64e63d482dc'::uuid, 'Continuous data', FALSE, 1),('6b5537da-ed0e-4980-8e35-3e3c49c8a24d'::uuid, '980f4c50-40b7-4835-8d90-b64e63d482dc'::uuid, 'Topography', TRUE, 2),('6c153f61-926b-4007-84f9-a544acd639e2'::uuid, '980f4c50-40b7-4835-8d90-b64e63d482dc'::uuid, 'Temporal information', FALSE, 3),('0de81d16-268e-4a31-8482-4426c6d138f7'::uuid, 'b9154b44-6e9d-4b28-80dd-77dbf68fb07b'::uuid, 'Because locations are the basis for mapping and allow linking information and measuring distances and areas.', TRUE, 0),('2be8c533-705a-4b83-8158-59d6af18f6c8'::uuid, 'b9154b44-6e9d-4b28-80dd-77dbf68fb07b'::uuid, 'Because place is an optional element and can be omitted for most maps.', FALSE, 1),('04cf5c29-2d66-4c49-8bd8-28e33df905f9'::uuid, 'b9154b44-6e9d-4b28-80dd-77dbf68fb07b'::uuid, 'Because place always determines the weather regardless of time.', FALSE, 2),('053eabf8-9032-4744-81de-eab081d61d6d'::uuid, 'b9154b44-6e9d-4b28-80dd-77dbf68fb07b'::uuid, 'Because place only matters for elevation measurements.', FALSE, 3),('a7a54f3d-347f-441c-82b0-04f86a75b758'::uuid, 'faba4cc1-057b-42d5-89a8-f4760326e799'::uuid, 'An optional element because some surface features change slowly and time can often be omitted.', TRUE, 0),('24cf04a3-283a-4576-84fa-3c60fec5258b'::uuid, 'faba4cc1-057b-42d5-89a8-f4760326e799'::uuid, 'Always required because no geographic data can be represented without time.', FALSE, 1),('06219dea-9c04-4483-8d50-27e1a70b9a72'::uuid, 'faba4cc1-057b-42d5-89a8-f4760326e799'::uuid, 'A feature that never changes and need not be recorded.', FALSE, 2),('d6bc680e-18c5-4863-8283-43333d71e9c0'::uuid, 'faba4cc1-057b-42d5-89a8-f4760326e799'::uuid, 'A measurement only used for elevation data.', FALSE, 3),('2f5095f9-320c-4c5b-8332-4c6787636eac'::uuid, '77e1365e-49df-4d6a-87c6-80209973c59d'::uuid, 'Lake', TRUE, 0),('ac3ed04b-279c-4931-8020-af2d4bf015f8'::uuid, '77e1365e-49df-4d6a-87c6-80209973c59d'::uuid, 'Elevation', FALSE, 1),('3a78d832-3585-470f-8b80-fc1415d3e874'::uuid, '77e1365e-49df-4d6a-87c6-80209973c59d'::uuid, 'Temperature', FALSE, 2),('18f229ae-515a-454a-8173-f400aef412ca'::uuid, '77e1365e-49df-4d6a-87c6-80209973c59d'::uuid, 'Atmospheric pressure', FALSE, 3),('ce0e72c5-7a48-48e2-8393-83cba6668c41'::uuid, 'b981d23f-d97d-49f6-8867-a1c1ba0cea39'::uuid, 'Elevation', TRUE, 0),('71c2c4f1-f6cb-4ad7-844e-b957ba26d129'::uuid, 'b981d23f-d97d-49f6-8867-a1c1ba0cea39'::uuid, 'A lake', FALSE, 1),('2b602b14-2475-45b3-85e8-e4d6a403ea99'::uuid, 'b981d23f-d97d-49f6-8867-a1c1ba0cea39'::uuid, 'A telephone tower', FALSE, 2),('da7a6afc-17a1-4a38-8dec-78b612595b52'::uuid, 'b981d23f-d97d-49f6-8867-a1c1ba0cea39'::uuid, 'An administrative boundary', FALSE, 3),('0712c472-dd5c-4632-8788-f67c74f1bfb3'::uuid, 'b2e87ccb-bb9d-496c-8015-cbff20acb50e'::uuid, 'Discrete objects', FALSE, 0),('58ad98b3-d68d-48fa-8333-d3acf19519f4'::uuid, 'b2e87ccb-bb9d-496c-8015-cbff20acb50e'::uuid, 'Continuous data', FALSE, 1),('f53b96e9-18bb-4012-8f11-a7842d163f18'::uuid, 'b2e87ccb-bb9d-496c-8015-cbff20acb50e'::uuid, 'Categorical clustering', TRUE, 2),('e9949bd2-9495-4ea0-8e39-8749b3f4d14f'::uuid, 'b2e87ccb-bb9d-496c-8015-cbff20acb50e'::uuid, 'Both discrete objects and continuous data', FALSE, 3),('218693b4-3325-46e6-8b9c-89cfefebe94a'::uuid, 'e21908ec-5da3-4073-8f3c-870542c89c93'::uuid, 'Hard copy maps (analogue maps)', TRUE, 0),('31686977-54b7-4dff-8511-13569f97e2ba'::uuid, 'e21908ec-5da3-4073-8f3c-870542c89c93'::uuid, 'Oral histories', FALSE, 1),('4c21460f-8d32-4a60-8260-1efda70beabe'::uuid, 'e21908ec-5da3-4073-8f3c-870542c89c93'::uuid, 'Folk tales', FALSE, 2),('b72f94a3-9c22-402e-8b42-ae1af376df51'::uuid, 'e21908ec-5da3-4073-8f3c-870542c89c93'::uuid, 'Mythological maps', FALSE, 3),('a914ed9a-0f67-4a60-8e5a-6a3bfa5cb5a0'::uuid, 'd7f7c578-2413-481c-8a81-1b6f8c6050e2'::uuid, 'Latitudinal and longitudinal coordinate values and elevation', TRUE, 0),('e667a301-a0a3-424c-8ee5-8c4e94fbc858'::uuid, 'd7f7c578-2413-481c-8a81-1b6f8c6050e2'::uuid, 'Raw satellite imagery without coordinates', FALSE, 1),('3e761512-700b-4f8d-8572-35cf0c972a2d'::uuid, 'd7f7c578-2413-481c-8a81-1b6f8c6050e2'::uuid, 'Cell size and raster resolution', FALSE, 2),('f4b1c3b6-45c7-40da-85c3-78c6729dcec2'::uuid, 'd7f7c578-2413-481c-8a81-1b6f8c6050e2'::uuid, 'Quality assurance reports', FALSE, 3),('c4730880-3753-422b-84a4-66ef2d52bc9d'::uuid, '5162eea8-921f-41ba-80fd-f57f5f2dd999'::uuid, 'Data generated by digitizers provides geo-referenced information, while images from scanners should be geo-referenced.', TRUE, 0),('94b5f60e-745c-4270-8c8e-b488d7f2239a'::uuid, '5162eea8-921f-41ba-80fd-f57f5f2dd999'::uuid, 'Scanners automatically produce geo-referenced vector files without further work.', FALSE, 1),('ce820b32-deff-48ea-8c31-41a95fa6a372'::uuid, '5162eea8-921f-41ba-80fd-f57f5f2dd999'::uuid, 'Digitizers produce satellite imagery directly.', FALSE, 2),('505e1d09-f25b-495b-8e3b-e8bf6d076e2e'::uuid, '5162eea8-921f-41ba-80fd-f57f5f2dd999'::uuid, 'Scanners and digitizers are only useful for analogue storage and cannot produce digital outputs.', FALSE, 3),('febce8f4-f283-4b8c-8a62-eb1725bc540c'::uuid, 'b130ac39-ddba-4c8c-80cd-018ba54f4505'::uuid, 'Digital data are easy to copy and transmit at very high speeds.', TRUE, 0),('17a8a5f3-a41d-48de-80c9-ca5ed24a5934'::uuid, 'b130ac39-ddba-4c8c-80cd-018ba54f4505'::uuid, 'Digital data never require quality checks.', FALSE, 1),('0310c1ca-5fec-461b-83ea-16f3cdd48067'::uuid, 'b130ac39-ddba-4c8c-80cd-018ba54f4505'::uuid, 'Digital data cannot be transformed or analyzed.', FALSE, 2),('43df5fd2-bd4b-47d1-8aa1-af0f32c84503'::uuid, 'b130ac39-ddba-4c8c-80cd-018ba54f4505'::uuid, 'Digital data take more physical storage space than paper.', FALSE, 3),('a29a494f-7aa5-4378-840e-60c4f6267c94'::uuid, '967e76ca-5bda-491f-8149-10dd2d91f5ae'::uuid, 'Points, lines and/or areas (polygons)', TRUE, 0),('06372448-bb30-439e-8c6b-58efe4ff9580'::uuid, '967e76ca-5bda-491f-8149-10dd2d91f5ae'::uuid, 'Only colors and photographs', FALSE, 1),('f9af9527-578c-4234-8b16-3433e8001a15'::uuid, '967e76ca-5bda-491f-8149-10dd2d91f5ae'::uuid, 'Only numbers and charts', FALSE, 2),('3c15cf27-854a-4103-8247-9b2ea7b13d6a'::uuid, '967e76ca-5bda-491f-8149-10dd2d91f5ae'::uuid, 'Only raster grids without vectors', FALSE, 3),('e8fda32c-3b90-4109-84cd-e2f6f52036c7'::uuid, 'b3c5ce7d-93f8-4d28-81a2-678d523ade80'::uuid, 'A vertex that starts or ends an arc segment', TRUE, 0),('958c80d1-43d0-4e7f-8fd7-12337612e932'::uuid, 'b3c5ce7d-93f8-4d28-81a2-678d523ade80'::uuid, 'A raster cell identified by row and column', FALSE, 1),('c4f9cf2b-a6eb-42bc-8da1-4b618f9ace31'::uuid, 'b3c5ce7d-93f8-4d28-81a2-678d523ade80'::uuid, 'A satellite used in GPS calculations', FALSE, 2),('471ad388-77c0-48d7-8de8-6f27182e7d56'::uuid, 'b3c5ce7d-93f8-4d28-81a2-678d523ade80'::uuid, 'A type of scanner for digitization', FALSE, 3),('72744c3e-d31d-49af-85be-a9294a55d8de'::uuid, '59e5a741-8a37-4b7d-8a06-61d7e6bef8b7'::uuid, 'By collections of contiguous cells', TRUE, 0),('d68bcca8-3c29-4013-8071-31a6890416ca'::uuid, '59e5a741-8a37-4b7d-8a06-61d7e6bef8b7'::uuid, 'By a single vertex pair', FALSE, 1),('7d3fc15f-f25c-4a1f-8d43-0b69d466918b'::uuid, '59e5a741-8a37-4b7d-8a06-61d7e6bef8b7'::uuid, 'By a list of node IDs only', FALSE, 2),('4c6a733c-c471-4969-8b63-11df0eb51f67'::uuid, '59e5a741-8a37-4b7d-8a06-61d7e6bef8b7'::uuid, 'By satellite orbital parameters', FALSE, 3),('057b6eaf-076d-49d2-843d-16ba62c4bd86'::uuid, '6d0fdd5a-1c14-489a-8718-fa458f771951'::uuid, 'Hardware', TRUE, 0),('4d44dc55-6a4a-46db-8ee7-e03a77b216f2'::uuid, '6d0fdd5a-1c14-489a-8718-fa458f771951'::uuid, 'Cuisine', FALSE, 1),('43e11b88-249c-4b7e-875f-16e408905aae'::uuid, '6d0fdd5a-1c14-489a-8718-fa458f771951'::uuid, 'Myth', FALSE, 2),('111da75e-7787-46eb-80bd-416da76c5eba'::uuid, '6d0fdd5a-1c14-489a-8718-fa458f771951'::uuid, 'Storytelling', FALSE, 3),('d2f6845b-5878-4db2-8db2-d0143fc96d3a'::uuid, '2f643454-2fa8-45cd-8bae-f4087db53ccb'::uuid, 'Dividing the Earth into lines of longitude and latitude', TRUE, 0),('c9c33efd-ea1c-4e72-8e8f-d6f18124a611'::uuid, '2f643454-2fa8-45cd-8bae-f4087db53ccb'::uuid, 'Cave paintings', FALSE, 1),('3c309cbe-f1d7-48f1-8fbb-ead86272f78a'::uuid, '2f643454-2fa8-45cd-8bae-f4087db53ccb'::uuid, 'Storytelling', FALSE, 2),('3f73ca91-5e2e-4251-813b-0a3a21b6b556'::uuid, '2f643454-2fa8-45cd-8bae-f4087db53ccb'::uuid, 'Hand-drawn mythological maps', FALSE, 3),('e73008e0-ee71-418c-8072-4f73a819979e'::uuid, '826490a3-6eeb-4fe1-8c1b-112a98aa7e2f'::uuid, 'True', FALSE, 0),('91d7c176-a81a-4a19-87b4-4760b6590dad'::uuid, '826490a3-6eeb-4fe1-8c1b-112a98aa7e2f'::uuid, 'False', TRUE, 1),('6af4fb21-60be-4094-88fa-02fb7aa3e2a6'::uuid, '970a2275-43b6-454d-8ec1-bb789ae32356'::uuid, 'True', TRUE, 0),('be7a282e-91d1-499e-820d-c3ab2c2d0bba'::uuid, '970a2275-43b6-454d-8ec1-bb789ae32356'::uuid, 'False', FALSE, 1),('0c29636b-4f8b-467c-806b-31e8a08a89f3'::uuid, '76551550-3dd5-4bb6-81fc-658b31adc364'::uuid, 'True', TRUE, 0),('22649f20-5802-4fd7-84dc-8294c8c7f2ab'::uuid, '76551550-3dd5-4bb6-81fc-658b31adc364'::uuid, 'False', FALSE, 1),('02863cd9-e2aa-4101-8c36-11c95becb250'::uuid, '7ac53e8e-49b1-46ce-85db-54dcb68fa81d'::uuid, 'True', TRUE, 0),('0dab06be-1208-40d3-8559-cfc3ff4d72ac'::uuid, '7ac53e8e-49b1-46ce-85db-54dcb68fa81d'::uuid, 'False', FALSE, 1) ON CONFLICT (id) DO UPDATE SET question_id = EXCLUDED.question_id, choice_text = EXCLUDED.choice_text, is_correct = EXCLUDED.is_correct, order_index = EXCLUDED.order_index;
INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'Health & PE', 'Unit 1', 'Molarum Grade 10 — Health & PE Unit 1: Health and Physical Education', 'Source-grounded Molarum Grade 10 Health & PE questions for Unit 1: Health and Physical Education.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('92c56bec-db6a-4c5e-88ce-65f5acc077ba'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'multiple_choice', 'Which of the following is NOT given in the text as an example of ''media''?', 'Gymnasium', 'The excerpt lists radio, television, newspaper and magazine as examples of media; a gymnasium is not a communication medium but a facility for sport.', 0),('f3770aec-6d88-4003-8830-079040b65be1'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'multiple_choice', 'According to the text, which type of media is described as the oldest?', 'Print media', 'The excerpt states that print media is the oldest of all types of media and includes newspapers, journals, books and magazines.', 1),('19eee1a7-cef0-4533-87a5-131c38cbd0a2'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'multiple_choice', 'Which feature of the internet is emphasized in the excerpt?', 'It is easily accessible', 'The text describes the internet as easily accessible and the fastest information dissemination media, especially familiar to youth.', 2),('5b9e53eb-85ab-4626-84e9-2103b5df9e38'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'multiple_choice', 'How does the excerpt define ''infotainment''?', 'Providing information using entertaining mechanisms', 'The excerpt explains that infotainment delivers information to the public through entertaining mechanisms such as drama, talk shows and discussions.', 3),('72f2b4c7-3758-4bcc-8e31-b30d4a22a605'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'multiple_choice', 'Which of the following is NOT listed as one of the fundamental roles of media in the excerpt?', 'Regulating laws', 'The excerpt lists educating, entertaining and informing as the fundamental roles of media; it does not state that media regulate laws.', 4),('c87944b5-a9c7-4252-8927-172ccedb441e'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'multiple_choice', 'The excerpt indicates media coverage is highest for which of the following?', 'Football World Cup and Olympic Games', 'The text states that media focus on professional and championship sports and that coverage for the football World Cup and Olympic Games is very high.', 5),('2afbfb90-3e81-4603-8a69-89d54695a30d'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'multiple_choice', 'Who does the excerpt identify as the professionals responsible for reporting sporting events?', 'Journalists', 'The excerpt explains that well trained and professional individuals known as journalists gather and report sporting events, with sport journalists responsible for sport reporting.', 6),('8f59bb02-d96c-430c-8590-800445075c8c'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'multiple_choice', 'Which of these is NOT given as an example of print media in the text?', 'Radio', 'The excerpt names newspaper, journal, book and magazine as print media; radio is categorized as broadcast (electronic) media.', 7),('b0214485-9eee-4b56-8997-ecf197aad639'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'multiple_choice', 'According to the text, mass media contributes to sport development mainly by:', 'Influencing sport development objectives', 'The excerpt explains that mass media is an important means for sport development because it embraces people''s interest in sport and influences sport development objectives.', 8),('a6a24b77-d7c7-4578-88b2-9cb696541040'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'multiple_choice', 'Which statement best reflects the excerpt''s view on media attention and inclusivity?', 'Media generally focuses more on championship and professional sports than on recreational and disability sports', 'The text states that broadcast attention is higher for major professional events while recreational, educational, disability and local sports receive little attention, which affects their development.', 9),('67141e4b-691f-4094-89eb-c584fc61bd8c'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'multiple_choice', 'Why does the excerpt say sport and religion are closely linked?', 'Because both involve ritual and shared values', 'The excerpt explains that both sport and religion involve ritual, devotion and share values such as fairness, equity and respect which strengthen social interaction.', 10),('d2c9cfa6-d824-445c-8878-97a925edfd14'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'multiple_choice', 'Which organization is identified in the excerpt as the global body that monitors anti-doping?', 'World Anti-Doping Agency (WADA)', 'The excerpt names the World Anti-Doping Agency (WADA) as the independent organization founded by the sports movement and governments to monitor and ensure anti-doping worldwide.', 11),('25bb7b10-a5fa-4ae4-84db-bf9a2bec5a21'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'multiple_choice', 'Before ETH-NADO was established, where was the basic rule of doping managed according to the text?', 'Under the criminal code of the Federal Democratic Republic of Ethiopia', 'The excerpt explains that before ETH-NADO, the basic rule of doping was managed under the criminal code (proclamation No 414/2004 Article 526) of Ethiopia.', 12),('2f1e92f7-5aed-4c5f-8c02-6bcf01f84733'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'multiple_choice', 'By which regulation number was ETH-NADO established as stated in the excerpt?', 'Regulation No. 400/2017', 'The excerpt states that ETH-NADO was established by the FDRE council minister’s Regulations No. 400/2017 to enhance doping-free sport in Ethiopia.', 13),('75c1e6c3-5e08-4181-8084-78eb493872f5'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'multiple_choice', 'Which of the following is listed in the excerpt as an anti-doping rule violation?', 'Presence of a prohibited substance in an athlete’s sample', 'The excerpt lists presence of a prohibited substance or its metabolites or markers in an athlete’s sample as one of the anti-doping rule violations accepted by ETH-NADO.', 14),('17d0ac52-6795-4c28-8499-3b8ee2935f52'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'multiple_choice', 'Which of these actions is NOT listed as an anti-doping rule violation in the excerpt?', 'Publishing an athlete''s training plan', 'The excerpt provides a list of violations including trafficking, prohibited association and complicity, but it does not mention publishing an athlete''s training plan.', 15),('4b07592c-92f2-4daa-8944-3f295814ef2e'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'multiple_choice', 'What range of sanction for anti-doping violations is given in the excerpt?', 'Two years to a lifetime ban', 'The excerpt states that sanctions for anti-doping violations may range from two years to a lifetime ban, and cases may also go to court under criminal code provisions.', 16),('9239a799-11dd-4226-8987-603005759a91'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'multiple_choice', 'Which Ethiopian long distance runner is mentioned as taking part in peace development and founding schools?', 'Haile Gebresilassie', 'The excerpt names Haile Gebresilassie as a well-known Ethiopian long distance runner who is a member of country elders and founded two schools, participating in peace development.', 17),('04f5fefd-629c-4cee-8a6d-3cce70e7da8d'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'multiple_choice', 'Which player is cited in the excerpt as financing schools and a hospital in his native country?', 'Sadio Mane', 'The text states that Sadio Mane financed a large amount of money for school building and a hospital in his native Senegal and donated football kits to poor children.', 18),('861d6f72-9243-4912-8300-575c22ce1e47'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'multiple_choice', 'Which player was appointed to a truth and reconciliation commission after civil war and established a foundation in 2007?', 'Didier Drogba', 'The excerpt describes Didier Drogba''s involvement in Côte d’Ivoire''s post-war truth and reconciliation commission and notes he established the Didier Drogba Foundation in 2007.', 19),('36210afd-38a4-4971-8313-7a216c1b5571'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'true_false', 'The term ''mass media'' addresses a large population.', 'True', 'The excerpt defines mass media as a form of mass communication that spreads information to the public and addresses large populations.', 20),('831bc553-7156-4c7a-8994-18d94f052b15'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'true_false', 'Print media was the frontline source of news before the rise of radio and television.', 'True', 'The text states that before the rise of radio and television, print media was at the frontline in addressing the public about national and global news.', 21),('ad2d6b03-7a3f-4df2-8a99-12013e7bdd5a'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'true_false', 'The excerpt states that sport and religion are open to all human beings regardless of gender and disability.', 'True', 'The excerpt explicitly notes that both sport and religion are open for all human beings regardless of gender, disability, race and many others.', 22),('13c801fa-171e-4e7f-8fe8-ae5b8ff66e90'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'true_false', 'Ethiopia missed the 1976 Olympic Games because it supported New Zealand’s sporting links with apartheid.', 'False', 'The excerpt explains Ethiopia missed the 1976 Olympics as part of an African and Arab protest against New Zealand’s sporting links with apartheid, not because it supported those links.', 23),('2f1c1a8f-2455-4884-834b-587fa04a0e75'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'fill_blank', 'Name three main contents listed under the unit''s Main Contents.', 'Sport and media; Sport and religion; Sport and politics', 'The unit lists as main contents: Sport and media, Sport and religion, Sport and politics, among others such as famous sports persons’ humanitarian activities and anti-doping rules.', 24),('66ca4942-8833-43e0-801b-556d271a94b7'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'fill_blank', 'Give one learning competency for the ''Sport and media'' lesson.', 'Discuss the role of media in sport.', 'The learning competency for the lesson includes discussing the role of media in sport and relating sport''s role with social values, so discussing the role of media is explicitly listed.', 25),('98993e3b-eaa1-43e0-80be-27dbf07ad5d6'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'fill_blank', 'List two shared values between sport and religion mentioned in the text.', 'Fairness and respect', 'The excerpt notes shared values such as fairness, equity and respect between sport and religion that strengthen social interaction.', 26),('c71d61fc-6b64-49fd-8d1a-f524b1022761'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'fill_blank', 'Briefly explain why limited media coverage for recreational and disability sports affects their development.', 'Limited coverage reduces public attention and support, which hinders their development and resource allocation.', 'The text explains that recreational, educational, disability and local sports receive little media attention and that this lack of attention affects their development and inclusivity.', 27),('391f03c1-6461-48d5-8864-bb7b09a3ec32'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'fill_blank', 'Give one example of an ''infotainment'' mechanism mentioned in the excerpt.', 'Talk shows', 'The excerpt gives examples of infotainment mechanisms such as drama, talk shows and discussions used to provide information while entertaining.', 28),('2a242ae6-7109-435b-8221-e6e5035ef507'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'fill_blank', 'State one way famous sports persons contribute to their countries according to the excerpt.', 'They participate in peace development and humanitarian activities.', 'The excerpt describes that superstar athletes take part in peace development and humanitarian activities, such as founding schools and supporting communities.', 29),('5128f411-b620-41e1-8b65-05c65a14c484'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'fill_blank', 'Briefly describe the role of WADA as given in the excerpt.', 'WADA monitors and ensures anti-doping activities worldwide as an independent organization founded by the sports movement and governments.', 'The excerpt states that the World Anti-Doping Agency is an independent organization jointly founded by sports movements and governments to control and protect against doping globally.', 30),('bb90b182-06b1-4c8d-8d8c-bc0ce34eb01a'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'fill_blank', 'According to the excerpt, what is the relationship between sport development and national development?', 'Sport development is a step toward national development.', 'The excerpt explicitly states that sport development is a step toward national development and media can be used to embrace public interest in sport to support that development.', 31),('0771d229-3392-42e8-815a-951861a86713'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'fill_blank', 'How many types of media does the excerpt explicitly list?', '3', 'The excerpt states there are three types of media: print media, broadcast media and internet.', 32),('b7e2f6d8-1aae-4c83-8833-b467d89aa598'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'fill_blank', 'In which year was the World Anti-Doping Code first adopted according to the excerpt?', '2003', 'The excerpt indicates the World Anti-Doping Code was first adopted in 2003.', 33),('4f6022d8-d4e6-4cf4-8b75-219e75784321'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'fill_blank', 'In which year did the World Anti-Doping Code first take effect as given in the text?', '2004', 'The text states the code took effect in 2004 after being adopted in 2003.', 34),('2f703416-deb5-4a8f-8507-490d26fcff47'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'fill_blank', 'The World Anti-Doping Code was amended effective 1 January in which year according to the excerpt?', '2009', 'The excerpt notes the World Anti-Doping Code was amended effective 1 January 2009.', 35),('a024167b-dac9-4fab-8515-a30c6967299f'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'fill_blank', 'How many articles does the newly revised 2021 WADA code have as stated in the excerpt?', '27', 'The excerpt explicitly states that the newly revised 2021 WADA code has 27 articles.', 36),('738293bf-35d8-4206-8b22-d04026c91260'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'fill_blank', 'Under which proclamation and Article was the basic rule of doping managed before ETH-NADO, as given in the excerpt?', 'Proclamation No. 414/2004, Article 526', 'The excerpt indicates that before ETH-NADO the basic rule of doping was managed under proclamation No. 414/2004 Article 526 in the Ethiopian criminal code.', 37),('fd9188ad-f293-4ddb-8d21-0e2633d0a804'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'fill_blank', 'In which year was ETH-NADO established by Regulations No. 400/2017 as stated in the excerpt?', '2017', 'The excerpt states that ETH-NADO was established by FDRE council minister’s Regulations No. 400/2017, which indicates the year 2017.', 38),('e01472d5-a7fb-4968-80c2-8a4a41673495'::uuid, '9953dbd7-dbbf-4138-8043-58e6f81aafd7'::uuid, 'fill_blank', 'How many Olympic Games listed in the excerpt did Ethiopia miss (years given as 1976, 1984 and 1988)?', '3', 'The excerpt lists three Olympic Games that Ethiopia missed: 1976, 1984 and 1988, therefore the count is three.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
